import { PlaneGeometry, MeshBasicNodeMaterial, Group, Euler } from 'three/webgpu';
import { uniform, texture, vec2, vec4, mul, smoothstep, uv, screenUV, positionWorld, cameraPosition, dot, normalize, vec3, mix, uniformArray } from 'three/tsl';
import { gsap } from 'gsap';
import { ExponentialMovingAverage } from '@/primitives';

const REGION_WIDTH = 512;
const REGION_HEIGHT = 320;
const ASPECT_RATIO = REGION_WIDTH / REGION_HEIGHT;
const PLANE_SIZE = 2.8;

export default function createNode(config, ctx) {
  const group = new Group();
  group.position.set(0, -0.3, 0);

  // Materials
  const mat = new MeshBasicNodeMaterial({ 
    transparent: true,
    depthWrite: false,
    side: ctx.THREE.DoubleSide,
  });

  // Gradient overlay for dark paper theme
  const gradientMix = uniform(0.3);
  const colorNode = vec4(
    mix(
      vec3(0.91, 0.925, 0.95), // paper
      vec3(0.04, 0.04, 0.06), // surface
      gradientMix
    ),
    0.85
  );

  // Grain texture overlay (engineered subtle grain)
  const grainTex = texture(config.imageUrl);
  const grainNode = vec4(grainTex, uv());
  const grainStrength = uniform(0.08);

  const grainMix = mix(
    colorNode,
    vec4(grainNode.rgb, 1.0),
    grainStrength
  );

  // Black/white grain noise
  const noiseNode = grainNode.r;
  const grainOverlay = smoothstep(0.45, 0.55, noiseNode);

  const finalColor = mix(
    grainMix,
    vec4(
      mix(vec3(0.0), vec3(1.0), grainOverlay),
      0.02
    ),
    0.15
  );

  mat.colorNode = finalColor;

  // Geometry with atlas UV offsets
  const geometry = new PlaneGeometry(
    PLANE_SIZE * ASPECT_RATIO, 
    PLANE_SIZE, 
    32, 32
  );

  // Adjust UVs for atlas region (0,0,512,320 in a 512x320 region)
  const uvs = geometry.attributes.uv;
  for (let i = 0; i < uvs.count; i++) {
    const u = uvs.getX(i);
    const v = uvs.getY(i);
    // Map UV to atlas region: source rect at (0,0) with size (512,320)
    // Since atlas is 512x320, UVs map directly
    uvs.setXY(i, u, v);
  }
  uvs.needsUpdate = true;

  const mesh = new ctx.THREE.Mesh(geometry, mat);
  group.add(mesh);

  // Subtle gradient edge via vertex colors
  const vertexCount = geometry.attributes.position.count;
  const colors = new Float32Array(vertexCount * 3);
  for (let i = 0; i < vertexCount; i++) {
    const x = geometry.attributes.position.getX(i);
    const y = geometry.attributes.position.getY(i);
    // Vertical gradient: paper at top, surface at bottom
    const t = (y / (PLANE_SIZE / 2) + 1) / 2;
    const mixVal = smoothstep(0.2, 0.6, t);
    colors[i * 3] = mix(0.91, 0.04, mixVal);
    colors[i * 3 + 1] = mix(0.93, 0.04, mixVal);
    colors[i * 3 + 2] = mix(0.95, 0.06, mixVal);
  }
  geometry.setAttribute('color', new ctx.THREE.BufferAttribute(colors, 3));

  // Color gradient from vertex colors
  mat.vertexColors = true;

  // Subtle billboard effect using shader nodes
  const billboardRot = uniform(new Euler(0, 0, 0));

  // Simple billboard: face camera on Y axis
  const cameraPos = uniform(new ctx.THREE.Vector3(0, 0, 10));
  const lookAtDir = normalize(cameraPos.sub(positionWorld));
  const up = vec3(0, 1, 0);
  const right = normalize(cross(up, lookAtDir));
  const newUp = cross(lookAtDir, right);

  // Apply rotation to geometry instance
  const billboardMatrix = mat3(right, newUp, lookAtDir);

  // Use billboard rotation in vertex shader via modelViewPosition
  // Simple approach: rotate mesh to face camera
  mesh.lookAt(0, -0.3, 10);

  // Keep slight tilt for depth
  mesh.rotation.z = 0.03;
  mesh.rotation.x = -0.02;

  // Reflective specular node for subtle sheen
  const reflectionIntensity = uniform(0.15);
  const viewDir = normalize(cameraPosition.sub(positionWorld));
  const halfDir = normalize(viewDir.add(vec3(0, 1, 0)));
  const spec = pow(max(dot(normalize(vec3(0, 0, 1)), halfDir), 0.0), 32.0);
  const specColor = vec4(vec3(0.95, 0.96, 0.98), spec.mul(reflectionIntensity));

  mat.colorNode = mat.colorNode.add(specColor.mul(0.3));

  // Load grain texture
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    grainTex.value = tex;
    mat.needsUpdate = true;
  });

  // Metadata & event handlers
  group.userData = {
    type: 'journal-card-1',
    handlers: {},
    cleanup: () => {
      mat.dispose();
      geometry.dispose();
    }
  };

  return group;
}
